from pathlib import Path
import base64, gzip

FILES = {
    'ios/Basir/Design/BasirDesignSystem.swift': '',
    'ios/Basir/Views/HomeView.swift': '',
    'ios/Basir/Views/VisionView.swift': '',
    'ios/Basir/Views/DocumentsView.swift': '',
    'ios/Basir/Views/MoreView.swift': '',
    'ios/Basir/Views/DescribeHubView.swift': '',
    'ios/Basir/Views/AdvancedToolsView.swift': '',
}

for rel, payload in FILES.items():
    path = Path(rel)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

print(f"Applied graphics-first redesign to {len(FILES)} Swift files")
